<div class="page-heading"><div><span class="eyebrow">Parent dashboard</span><h1>Hello, <?= e(explode(' ', current_user()['name'])[0]) ?>.</h1><p>See each child’s next due dose and the requests waiting in the appointment flow.</p></div><a class="button" href="<?= e(url('parent.hospitals')) ?>">Book hospital</a></div>
<?php if (!$children): ?><section class="welcome-card"><div><span class="eyebrow">First step</span><h2>Add your child’s details</h2><p>Once the date of birth is saved, the dashboard calculates vaccination dates automatically.</p><a class="button" href="<?= e(url('parent.children')) ?>">Add child</a></div><span class="welcome-shape" aria-hidden="true"></span></section><?php else: ?>
<section class="child-strip" aria-label="Registered children"><?php foreach ($children as $child): ?><article><span class="initial-badge"><?= e(mb_strtoupper(mb_substr($child['name'], 0, 1))) ?></span><div><h2><?= e($child['name']) ?></h2><p><?= e(age_label($child['date_of_birth'])) ?> · <?= (int) $child['completed_doses'] ?> completed dose<?= (int) $child['completed_doses'] === 1 ? '' : 's' ?></p></div><a href="<?= e(url('parent.children', ['edit' => $child['id']])) ?>">Details</a></article><?php endforeach; ?></section>
<?php endif; ?>
<div class="dashboard-columns">
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">Dashboard notifications</span><h2>Vaccination dates</h2></div></div>
<?php if (!$schedule): ?><div class="empty-inline"><p><?= $children ? 'All catalogued doses are recorded.' : 'Add a child to calculate dates.' ?></p></div><?php else: ?><div class="due-list"><?php foreach ($schedule as $dose): ?><?php $due = new DateTimeImmutable($dose['due_date']); $today = new DateTimeImmutable('today'); $state = $due < $today ? 'overdue' : ($due <= $today->modify('+30 days') ? 'due-soon' : 'later'); ?><article class="due-<?= e($state) ?>"><span class="due-marker"></span><div><h3><?= e($dose['vaccine_name']) ?> · <?= e($dose['dose_label']) ?></h3><p><?= e($dose['child_name']) ?> · <?= $state === 'overdue' ? 'Due since ' : 'Due ' ?><?= e(display_date($dose['due_date'])) ?></p></div><?php if ($dose['is_booked']): ?><span class="status status-approved">Requested</span><?php else: ?><a class="button button-small button-secondary" href="<?= e(url('parent.hospitals')) ?>">Book</a><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
</section>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">Requests</span><h2>Upcoming appointments</h2></div><a href="<?= e(url('parent.bookings')) ?>">View all</a></div>
<?php if (!$appointments): ?><div class="empty-inline"><p>No upcoming appointment requests.</p></div><?php else: ?><div class="appointment-stack"><?php foreach ($appointments as $appointment): ?><article><div class="date-tile"><strong><?= e(display_date($appointment['appointment_date'], 'd')) ?></strong><span><?= e(display_date($appointment['appointment_date'], 'M')) ?></span></div><div><h3><?= e($appointment['child_name']) ?></h3><p><?= e($appointment['vaccine_name']) ?> · <?= e(display_date($appointment['appointment_time'], 'g:i A')) ?></p><small><?= e($appointment['hospital_name']) ?></small></div><span class="status status-<?= e($appointment['status']) ?>"><?= e(status_label($appointment['status'])) ?></span></article><?php endforeach; ?></div><?php endif; ?>
</section></div>
